import json

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message


class QuexaGrader(Component):
    display_name = "Quexa Grader"
    description = "Menghitung skor pilihan ganda tanpa LLM."
    icon = "Calculator"
    name = "QuexaGrader"

    inputs = [
        MessageTextInput(
            name="payload",
            display_name="Quiz dan Jawaban JSON",
            required=True,
        ),
    ]

    outputs = [
        Output(
            name="hasil",
            display_name="Hasil Penilaian",
            method="grade_quiz",
        ),
    ]

    def grade_quiz(self) -> Message:
        try:
            data = json.loads(self.payload)

            if not isinstance(data, dict):
                raise ValueError("Input harus berupa objek JSON.")

            soal = data.get("soal")
            jawaban = data.get("jawaban")

            if not isinstance(soal, list) or not soal:
                raise ValueError("'soal' harus berupa array yang tidak kosong.")
            if not isinstance(jawaban, dict):
                raise ValueError("'jawaban' harus berupa objek.")

            ids = []
            for item in soal:
                if not isinstance(item, dict):
                    raise ValueError("Setiap soal harus berupa objek.")
                sid = item.get("id")
                if not isinstance(sid, str) or not sid.strip():
                    raise ValueError("Setiap soal harus memiliki ID.")
                ids.append(sid)

            if len(ids) != len(set(ids)):
                raise ValueError("ID soal tidak boleh berulang.")
            if set(jawaban) - set(ids):
                raise ValueError("Ada jawaban untuk ID soal yang tidak dikenal.")

            benar = 0
            belum_dijawab = 0
            detail = []
            topik = {}

            for item in soal:
                sid = item["id"]
                konsep = item.get("topik")
                if not isinstance(konsep, str) or not konsep.strip():
                    raise ValueError(f"Topik {sid} tidak valid.")
                konsep = konsep.strip()

                kunci = item.get("kunci")
                if not isinstance(kunci, str) or kunci not in "ABCD" or len(kunci) != 1:
                    raise ValueError(f"Kunci {sid} harus A, B, C, atau D.")

                pilihan = jawaban.get(sid)
                if pilihan is not None:
                    if not isinstance(pilihan, str):
                        raise ValueError(f"Jawaban {sid} harus berupa huruf.")
                    pilihan = pilihan.strip().upper() or None

                if pilihan is not None and pilihan not in ("A", "B", "C", "D"):
                    raise ValueError(f"Jawaban {sid} harus A, B, C, atau D.")

                tepat = pilihan == kunci
                benar += int(tepat)
                belum_dijawab += int(pilihan is None)

                statistik = topik.setdefault(
                    konsep, {"total": 0, "benar": 0, "salah": 0, "belum_dijawab": 0}
                )
                statistik["total"] += 1
                if tepat:
                    statistik["benar"] += 1
                elif pilihan is None:
                    statistik["belum_dijawab"] += 1
                else:
                    statistik["salah"] += 1

                detail.append({
                    "id": sid,
                    "topik": konsep,
                    "jawaban_user": pilihan,
                    "kunci": kunci,
                    "status": (
                        "belum_dijawab" if pilihan is None
                        else "benar" if tepat else "salah"
                    ),
                })

            hasil = {
                "status": "ok",
                "total_soal": len(soal),
                "benar": benar,
                "salah": len(soal) - benar - belum_dijawab,
                "belum_dijawab": belum_dijawab,
                "skor": round(100 * benar / len(soal), 2),
                "detail": detail,
                "ringkasan_topik": topik,
                "topik_perlu_diulang": [
                    nama for nama, nilai in topik.items()
                    if nilai["salah"] > 0
                ],
            }

        except (ValueError, TypeError) as error:
            hasil = {"status": "error", "pesan": str(error)}

        return Message(text=json.dumps(hasil, ensure_ascii=False))
